                          "default": 1
                        },
                        "valley": {
                          "type": "number",
                          "minimum": 0,
                          "maximum": 2,
                          "default": 1
                        }
                      },
                      "additionalProperties": false,
                      "required": [
                        "kind"
                      ]
                    },
                    {
                      "type": "object",
